import { add, update } from "@/api/operation/safeaccess/areacode";
import { Message } from "element-ui";
import { attrrelUpdate } from "@/api/cmdb/ciConfig";
export default {
  props: ['isShow', 'arrtId', 'type', 'formDetial'],
  data: function data() {
    return {
      saveLoading: false,
      typeList: null,
      rules: {
        parentName: [{
          required: true,
          message: '上级名称不能为空',
          trigger: 'blur'
        }],
        parentCode: [{
          required: true,
          message: '上级编码不能为空',
          trigger: 'blur'
        }],
        selfName: [{
          required: true,
          message: '编码名称不能为空',
          trigger: 'blur'
        }],
        selfCode: [{
          required: true,
          message: '编码不能为空',
          trigger: 'blur'
        }],
        url: [{
          required: true,
          message: '认证地址不能为空',
          trigger: 'blur'
        }],
        type: [{
          required: true,
          message: '类型不能为空',
          trigger: 'blur'
        }]
      }
    };
  },
  computed: {},
  mounted: function mounted() {
    if (!this.formDetial) {
      this.formDetial = {};
    }
    this.initTypes();
  },
  methods: {
    initTypes: function initTypes() {
      this.typeList = [];
      this.typeList.push({
        name: '市',
        id: '2'
      });
      this.typeList.push({
        name: '县',
        id: '3'
      });
    },
    selectionChange: function selectionChange(val) {
      this.selectionList = val;
    },
    submit: function submit() {
      var _this = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this.type == 'add') {
            _this.saveLoading = true;
            add([_this.formDetial]).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('添加成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          } else if (_this.type == 'edit') {
            _this.saveLoading = true;
            update([_this.formDetial]).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('修改成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          }
        }
      });
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    }
  }
};
